6	/**
7	 * Runs in {@code POST /api/owners} after the owner entity is built and before it is saved, within
8	 * the create transaction. Stamps the built owner with the deterministic
9	 * {@link Household#id(String, String) household id} for its lastName and postcode. Because the id
10	 * is derived from those two fields alone, every owner in a household computes the same value
11	 * automatically — no backfill of existing members is needed and no opt-in is required.
12	 */
13	public class AssignOwnerHousehold {
14	
15	    public void service(@Val Owner owner) {
16	        owner.setHouseholdId(Household.id(owner.getLastName(), owner.getPostcode()));
17	    }
18	}
