	@Test
	void coreNewOwnerCappedAtLevel3() throws Exception {
		ObjectNode o = withPostcode(ownerNode());
		o.put("email", uniqueEmail());
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.membershipLevel").value(3));
	}
}

